def transform(grid):
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                points[value] = (r, c)

    r, c = points[1]
    tr, tc = points[2]
    dr = 1 if tr > r else -1
    dc = 1 if tc > c else -1

    # Move diagonally until one coordinate is one cell away from the target,
    # then continue along the other axis until adjacent to the target.
    diagonal_steps = max(0, min(abs(tr - r), abs(tc - c)) - 1)
    for _ in range(diagonal_steps):
        r += dr
        c += dc
        out[r][c] = 3

    while max(abs(tr - r), abs(tc - c)) > 1:
        if abs(tr - r) > 1:
            r += dr
        elif abs(tc - c) > 1:
            c += dc
        out[r][c] = 3

    return out
